-- Official provider pages checked 2026-10-05T15:54:52.781Z. Exact addresses geocoded by US Census.
-- Listings remain pending until an admin approves. Pay is never inferred.
begin;
alter table public.opportunities add column if not exists compensation_basis text check(compensation_basis is null or compensation_basis in ('PER_VISIT','PER_MONTH','TOTAL_PROGRAM'));
set local search_path=public,extensions;
do $providers$
declare r jsonb; org uuid; facility uuid; listing uuid;
begin
for r in select value from jsonb_array_elements('[{"organization":"Xytex","facility":"Xytex Atlanta","title":"Sperm donor program · Atlanta","type":"SPERM","address":"730 Peachtree Street NE, Atlanta, GA 30308","source":"https://donatesperm.com/atlanta-office/","min":18,"max":38,"payMax":1400,"basis":"PER_MONTH","requirements":"Provider lists ages 18–38, high school education or higher, local residency, and a six-month commitment with at least two visits weekly. Published compensation is up to $1,400 per month after acceptance; it is not a guaranteed payment. Full screening and final eligibility are determined by Xytex.","lat":33.77458277297,"lon":-84.384751099204,"matchedAddress":"730 PEACHTREE ST, ATLANTA, GA, 30308","coordinateSource":"https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=730+Peachtree+Street+NE%2C+Atlanta%2C+GA+30308&benchmark=Public_AR_Current&format=json"},{"organization":"Xytex","facility":"Xytex Marietta","title":"Sperm donor program · Marietta","type":"SPERM","address":"709 Canton Rd, Marietta, GA 30060","source":"https://donatesperm.com/marietta-office/","min":18,"max":38,"payMax":1400,"basis":"PER_MONTH","requirements":"Provider lists ages 18–38, high school education or higher, local residency, and a six-month commitment with at least two visits weekly. Published compensation is up to $1,400 per month after acceptance; it is not a guaranteed payment. Full screening and final eligibility are determined by Xytex.","lat":33.969645791073,"lon":-84.547931155222,"matchedAddress":"709 CANTON RD NE, MARIETTA, GA, 30060","coordinateSource":"https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=709+Canton+Rd%2C+Marietta%2C+GA+30060&benchmark=Public_AR_Current&format=json"},{"organization":"CSL Plasma","facility":"CSL Plasma Smyrna","title":"Plasma donation · Smyrna","type":"PLASMA","address":"3201 South Cobb Drive, Smyrna, GA 30080","source":"https://www.cslplasma.com/center/123","min":18,"max":null,"payMax":null,"basis":null,"requirements":"Center page lists this Smyrna location as taking new donors. Compensation is not published on the cited center page. EarnAhead requires age 18 or older. Review provider screening requirements at the center before applying.","lat":33.875066321051,"lon":-84.531004706195,"matchedAddress":"3201 S COBB DR, SMYRNA, GA, 30080","coordinateSource":"https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=3201+South+Cobb+Drive%2C+Smyrna%2C+GA+30080&benchmark=Public_AR_Current&format=json"},{"organization":"BioLife Plasma Services","facility":"BioLife Morrow","title":"Plasma donation · Morrow","type":"PLASMA","address":"1968 Mount Zion Rd, Morrow, GA 30260","source":"https://www.biolifeplasma.com/locations/georgia","min":18,"max":null,"payMax":null,"basis":null,"requirements":"Provider Georgia directory lists this Morrow facility. Compensation is not published on the cited directory page. EarnAhead requires age 18 or older. Review center-specific screening requirements with BioLife.","lat":33.564756247945,"lon":-84.326082405455,"matchedAddress":"1968 MOUNT ZION RD, MORROW, GA, 30260","coordinateSource":"https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=1968+Mount+Zion+Rd%2C+Morrow%2C+GA+30260&benchmark=Public_AR_Current&format=json"},{"organization":"BioLife Plasma Services","facility":"BioLife Duluth","title":"Plasma donation · Duluth","type":"PLASMA","address":"1625 Pleasant Hill Rd, Duluth, GA 30096","source":"https://www.biolifeplasma.com/locations/georgia","min":18,"max":null,"payMax":null,"basis":null,"requirements":"Provider Georgia directory lists this Duluth facility. Compensation is not published on the cited directory page. EarnAhead requires age 18 or older. Review center-specific screening requirements with BioLife.","lat":33.945509133646,"lon":-84.125548123405,"matchedAddress":"1625 PLEASANT HILL RD NW, DULUTH, GA, 30096","coordinateSource":"https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=1625+Pleasant+Hill+Rd%2C+Duluth%2C+GA+30096&benchmark=Public_AR_Current&format=json"}]'::jsonb) loop
select id into listing from opportunities where data_source='PROVIDER' and external_id=(r->>'source')||':'||(r->>'facility');
if listing is not null then continue;end if;
select id into org from organizations where name=r->>'organization' limit 1;
if org is null then insert into organizations(name)values(r->>'organization') returning id into org;end if;
insert into locations(organization_id,name,address,position)values(org,r->>'facility',r->>'address',ST_SetSRID(ST_MakePoint((r->>'lon')::float,(r->>'lat')::float),4326)::geography) returning id into facility;
insert into opportunities(organization_id,location_id,title,opportunity_type,minimum_age,maximum_age,compensation_min,compensation_max,compensation_basis,data_source,external_id,source_url,review_status,verified,active)values(org,facility,r->>'title',(r->>'type')::opportunity_type,(r->>'min')::int,(r->>'max')::int,NULL,(r->>'payMax')::numeric,r->>'basis','PROVIDER',(r->>'source')||':'||(r->>'facility'),r->>'source','PENDING_REVIEW',false,false) returning id into listing;
insert into eligibility_requirements(opportunity_id,published_requirement)values(listing,r->>'requirements');
end loop;end;$providers$;
commit;
select title,review_status,compensation_max,compensation_basis from public.opportunities where opportunity_type in ('PLASMA','SPERM');

